import type { JSX } from 'react';
import { PropsWithChildren } from 'react';
import { useTranslation } from 'react-i18next';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import packageJson from '@/../package.json';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faAt, faBug } from '@fortawesome/free-solid-svg-icons';
import { faGithub, faTwitter } from '@fortawesome/free-brands-svg-icons';
import { appInfo } from 'lib/app-info';

export const Footer = (): JSX.Element => {
  const { t } = useTranslation('common');

  return (
    <div className="flex flex-col md:flex-row items-center md:justify-between w-full p-1.5 md:p-3 text-green-900 bg-opacity-80 backdrop-saturate-200 backdrop-blur bg-green-100 border-green-100 fixed bottom-0">
      <div className="flex flex-row items-center">
        <FooterText link={`${appInfo.app.source}${appInfo.app.releasesUri}/${packageJson.version}`}>
          {t('app-version', { version: appInfo.app.version })}
        </FooterText>
        <FooterIcon content={t('app-source')} link={appInfo.app.source}>
          <FontAwesomeIcon className={'text-xl text-black'} icon={faGithub} />
        </FooterIcon>
        <FooterIcon
          content={t('app-issues')}
          link={`${appInfo.app.source}${appInfo.app.issuesUri}`}
        >
          <FontAwesomeIcon className={'text-xl text-black'} icon={faBug} />
        </FooterIcon>
      </div>
      <div className="flex flex-row items-center">
        <FooterText>{t('app-creator', { name: appInfo.author.name })}</FooterText>
        <FooterIcon content={t('author.github-profile')} link={appInfo.author.profile}>
          <FontAwesomeIcon className={'text-xl text-black'} icon={faGithub} />
        </FooterIcon>
        <FooterIcon
          content={t('author.twitter', { handle: appInfo.author.twitter.name })}
          link={appInfo.author.twitter.link}
        >
          <FontAwesomeIcon className={'text-xl text-blue-700'} icon={faTwitter} />
        </FooterIcon>
        <FooterIcon content={t('author.send-email')} link={`mailto:${appInfo.author.email}`}>
          <FontAwesomeIcon className={'text-xl text-black'} icon={faAt} />
        </FooterIcon>
      </div>
    </div>
  );
};

interface FooterTextProps {
  link?: string;
  ariaLabel?: string;
}

const FOOTER_TEXT_CLASS = 'flex font-sans text-sm mx-1.5';

const FooterText = ({
  link,
  ariaLabel,
  children,
}: PropsWithChildren<FooterTextProps>): JSX.Element =>
  link ? (
    <a
      className={FOOTER_TEXT_CLASS}
      href={link}
      target="_blank"
      rel="noreferrer"
      aria-label={ariaLabel}
    >
      {children}
    </a>
  ) : (
    <p className={FOOTER_TEXT_CLASS}>{children}</p>
  );

interface FooterIconProps extends FooterTextProps {
  content: string;
  link: string;
}

const FooterIcon = ({
  content,
  link,
  children,
}: PropsWithChildren<FooterIconProps>): JSX.Element => (
  <Tooltip>
    <TooltipTrigger asChild>
      <FooterText link={link} ariaLabel={content}>
        {children}
      </FooterText>
    </TooltipTrigger>
    <TooltipContent>{content}</TooltipContent>
  </Tooltip>
);
