import { Dispatch, SetStateAction } from 'react';
import { GuitarType } from './constants';

interface Instruments {
  [name: string]: InstrumentMain;
}

interface InstrumentMain {
  name: string;
  fretsOnChord: number;
  strings: number;
  numberOfChords: number;
}

interface Tunings {
  [name: string]: string[];
}

export interface ChordPosition {
  frets: number[];
  fingers: number[];
  baseFret: number;
  barres?: number[];
  capo?: boolean;
  midi: number[];
  notes?: string[];
}
export interface ChordDetail {
  key: string;
  suffix: string;
  positions: ChordPosition[];
}

interface Chord {
  [name: string]: ChordDetail[];
}

export interface Instrument {
  main: InstrumentMain;
  keys: string[];
  suffixes: string[];
  tunings: Tunings;
  chords: Chord;
}

export interface ChordsHook {
  chords: ChordDetail[];
  chord?: ChordDetail;
  setChord: Dispatch<SetStateAction<ChordDetail | undefined>>;
}

interface ChordDb {
  guitar: Instrument;
  ukulele: Instrument;
  instruments: Instruments;
}

let guitar: Instrument | undefined;
let ukulele: Instrument | undefined;
let instruments: Instruments | undefined;
let cache: Promise<ChordDb> | undefined;

export const loadChordDb = (): Promise<ChordDb> => {
  cache ??= Promise.all([
    import('@tombatossals/chords-db/lib/guitar.json'),
    import('@tombatossals/chords-db/lib/ukulele.json'),
    import('@tombatossals/chords-db/lib/instruments.json'),
  ]).then(([guitarModule, ukuleleModule, instrumentsModule]) => {
    guitar = guitarModule.default as Instrument;
    ukulele = ukuleleModule.default as Instrument;
    instruments = instrumentsModule.default as Instruments;
    return { guitar, ukulele, instruments };
  });
  return cache;
};

const getInstrument = (instrument: string): Instrument => {
  if (!guitar || !ukulele) {
    throw new Error('chord-db has not been loaded yet — call loadChordDb() first');
  }
  switch (instrument) {
    case guitar.main.name:
      return guitar;
    case ukulele.main.name:
      return ukulele;
    default:
      throw new Error(`Unsupported CHORD instrument: ${instrument}`);
  }
};

export const getInstruments = (): Instruments => {
  if (!instruments) {
    throw new Error('chord-db has not been loaded yet — call loadChordDb() first');
  }
  return instruments;
};

const getChords = (instrument: string): ChordDetail[] =>
  Object.values(getInstrument(instrument).chords).flat();

export const chordTuning = (instrument: string): Tunings => getInstrument(instrument).tunings;

export const handleSelectionForChords = (
  guitarType: GuitarType,
  selectedKey: string | undefined,
  isSupported: (guitarType: GuitarType) => boolean,
  getChords: (instrument: string, key: string) => ChordDetail[],
  setChords: Dispatch<SetStateAction<ChordDetail[]>>,
  setChord: Dispatch<SetStateAction<ChordDetail | undefined>>,
  chord?: ChordDetail
): void => {
  if (isSupported(guitarType) && !!selectedKey) {
    const chords = getChords(guitarType.name, selectedKey);
    setChords(chords);
    if (chords.length === 1) {
      setChord(chords[0]);
    }
    if (chords.length > 1) {
      setChord(chords.find((type) => type.suffix === chord?.suffix));
    }
  } else {
    setChords([]);
    setChord(undefined);
  }
};

export const chordsForKey = (instrument: string, key: string): ChordDetail[] =>
  getChords(instrument).filter((chord) => chord.key === key);

export const chordModels = (instrument: string, key: string, name: string): ChordDetail[] =>
  getChords(instrument).filter((chord) => chord.key === key && chord.suffix === name);

export const chordNamesForKey = (instrument: string, key: string): string[] =>
  chordsForKey(instrument, key).map((chord) => chord.suffix);
